insert into capabilities (slug, label, icon, animation_type, description, applications, materials, use_cases, sort_order) values ('cnc-routing', 'CNC Routing', 'Cog', 'route', 'Computer-controlled routing for precise profiles, cutouts and edge detailing on flat sheet stock, guided directly by your drawing or CAD file.', ARRAY['Machine panels', 'Enclosure cutouts', 'Signage components', 'Display fixtures'], ARRAY['Acrylic', 'Polycarbonate'], ARRAY['Panels with multiple cutouts and mounting holes', 'Parts requiring consistent repeat geometry across a production run', 'Components with curved or irregular edge profiles'], 0);
