insert into capabilities (slug, label, icon, animation_type, description, applications, materials, use_cases, sort_order) values ('polycarbonate-cutting', 'Polycarbonate Cutting', 'Shield', 'cut', 'Cutting of polycarbonate sheet for components where impact resistance matters alongside dimensional accuracy.', ARRAY['Machine guards', 'Protective covers', 'Industrial glazing', 'Safety screens'], ARRAY['Polycarbonate'], ARRAY['Guards and covers for moving machine parts', 'Impact-resistant panels for industrial environments', 'Components requiring both clarity and durability'], 3);
insert into capabilities (slug, label, icon, animation_type, description, applications, materials, use_cases, sort_order) values ('acrylic-bending', 'Acrylic Bending', 'GitMerge', 'bend', 'Heat-formed bending of acrylic sheet to specified angles, producing folded or curved components without seams.', ARRAY['Display stands', 'Enclosure corners', 'Formed panels', 'Point-of-sale fixtures'], ARRAY['Acrylic'], ARRAY['Single-piece components that would otherwise need bonded corners', 'Formed panels with a consistent bend angle across a batch', 'Parts combining flat sections with a folded edge'], 4);
insert into capabilities (slug, label, icon, animation_type, description, applications, materials, use_cases, sort_order) values ('polycarbonate-bending', 'Polycarbonate Bending', 'GitBranch', 'bend', 'Controlled bending of polycarbonate sheet, taking advantage of its flexibility for formed components that need to withstand impact.', ARRAY['Curved guards', 'Formed covers', 'Protective housings', 'Structural panel corners'], ARRAY['Polycarbonate'], ARRAY['Curved guards that follow a machine''s contour', 'Formed covers requiring a folded edge for rigidity', 'Components where a bonded seam would be a weak point'], 5);
